(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  if (!s) return JSON.stringify({ error: '拿不到存储层（生产构建里没有这个入口）' });
  const out = {};

  const base = await s.listLibrary();
  out.builtinCount = base.length;

  // ① 用户自建一个元件
  const id1 = await s.saveLibraryComponent({
    name: 'XYZ 模块', category: '模块', purpose: '测试用', appearance: '一块小蓝板',
    polarity: '有方向，别插反', howToRead: '看丝印', source: 'user_created', author: '小明',
    commonMistakes: ['插反了不工作'], tags: ['测试'],
  });
  out.createdId = id1;
  const after1 = await s.listLibrary();
  out.afterCreate = after1.length;
  out.created = after1.find((c) => c.id === id1);

  // ② 同名不同 id：两个都要留着
  const id2 = await s.saveLibraryComponent({
    id: 'xyz-module-2', name: 'XYZ 模块', category: '模块', purpose: '同名的另一个',
    appearance: '另一块板', polarity: '无', howToRead: '-', source: 'user_created',
  });
  const after2 = await s.listLibrary();
  out.sameNameBothKept = after2.filter((c) => c.name === 'XYZ 模块').length;
  out.secondId = id2;

  // ③ 内置 id 不许占用
  let collision = '';
  try { await s.saveLibraryComponent({ id: 'resistor', name: '冒牌电阻', category: '基础元件', purpose: 'x', appearance: 'x', polarity: 'x', howToRead: 'x', source: 'user_created' }); }
  catch (e) { collision = e instanceof Error ? e.message : String(e); }
  out.builtinIdBlocked = collision;

  // ④ 从作品导入：同 id 跳过、内置跳过、新的加入
  const res = await s.importLibraryComponents([
    { id: id1, name: 'XYZ 模块', category: '模块', purpose: '本地已有', appearance: 'x', polarity: 'x', howToRead: 'x', source: 'user_created' },
    { id: 'resistor', name: '电阻', category: '基础元件', purpose: '内置已有', appearance: 'x', polarity: 'x', howToRead: 'x', source: 'builtin' },
    { id: 'from-friend-1', name: '朋友的自定义传感器', category: '传感器', purpose: '别人作品里带的', appearance: '带三根针的小板', polarity: '有正负极', howToRead: '看针脚标', source: 'user_created', author: '小红' },
  ], '示例作品A');
  out.importAdded = res.added.map((c) => c.id);
  out.importSkipped = res.skipped.map((c) => c.id);
  const imported = await s.getLibraryComponent('from-friend-1');
  out.importedSource = imported?.source;
  out.importedFrom = imported?.fromProject;

  // ⑤ 同 id 以用户库为准（覆盖内置？——内置 id 不允许重名，所以这里验证用户元件覆盖自己）
  await s.saveLibraryComponent({ id: id1, name: 'XYZ 模块（改名）', category: '模块', purpose: '改过的', appearance: 'x', polarity: 'x', howToRead: 'x', source: 'user_created', author: '小明' });
  const renamed = await s.getLibraryComponent(id1);
  out.renameKeptId = renamed?.id === id1;
  out.renameName = renamed?.name;

  // ⑥ 删不掉内置，删得掉自己的
  await s.removeLibraryComponent('resistor');
  out.builtinStillThere = !!(await s.getLibraryComponent('resistor'));
  await s.removeLibraryComponent(id1);
  await s.removeLibraryComponent(id2);
  await s.removeLibraryComponent('from-friend-1');
  const final = await s.listLibrary();
  out.finalCount = final.length;
  out.finalIds = final.map((c) => c.id);
  return JSON.stringify(out);
})()
